import SwiftUI

@Observable
final class LoginViewModel {
    var email = ""
    var password = ""
    var errorMessage: String?

    func submit() {
        guard email.contains("@") else {
            errorMessage = "Enter a valid email"
            return
        }
        guard password.count >= 8 else {
            errorMessage = "Password must be at least 8 characters"
            return
        }
        errorMessage = nil
    }
}

