struct OrderService {
    func calculateTotal(prices: [Double], discountPercent: Double = 0) -> Double {
        guard !prices.isEmpty else { return 0 }
        let subtotal = prices.reduce(0, +)
        return subtotal * (1 - discountPercent / 100)
    }
}
